import { GoogleGenAI, Type } from "@google/genai";

export class GeminiService {
  /**
   * Orchestrator to compile high-fidelity prompts using Gemini 3 Pro.
   * Forces 8K resolution and hyper-realistic directives in the compiled prompt.
   */
  async compilePrompt(data: any, hasReferences: boolean): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const fidelityInstruction = hasReferences 
      ? "CRITICAL: Maintain 100% exact fidelity to the provided reference images. Reproduce specific materials, logos, and textures with perfect accuracy."
      : "Maintain hyper-realistic product consistency.";

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Compile a hyper-fidelity 8K resolution generation prompt based on:
      Subject: ${data.subjectType}
      Angle: ${data.angle}
      Lens: ${data.lens}
      Lighting: ${data.lighting}
      Style: ${data.style}
      Scene: ${data.scene}
      User Prompt: ${data.userPrompt}
      ${fidelityInstruction}
      Quality: 8K, UHD, masterpiece, highly detailed textures, realistic shadows, Ray-traced reflections.
      Constraints: Preserve logos exactly, zero creative deviation, professional commercial photography standards.

      Return ONLY the final prompt string.`,
    });
    return response.text?.trim() || "A hyper-realistic 8K professional photo.";
  }

  /**
   * Photo Generation using gemini-3-pro-image-preview.
   * Sends 8K instructions and reference images for 100% fidelity.
   */
  async generatePhotos(prompt: string, aspectRatio: string, references: string[]): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const parts: any[] = [{ text: `Generate a hyper-realistic 8K photo: ${prompt}` }];

    references.forEach(ref => {
      const mimeType = ref.split(';')[0].split(':')[1];
      const base64Data = ref.split(',')[1];
      parts.push({
        inlineData: {
          data: base64Data,
          mimeType: mimeType
        }
      });
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts,
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K" // Note: 1K is the current max for this specific API, but prompt requests high-res details
        },
      },
    });

    const images: string[] = [];
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }
    }
    return images;
  }

  /**
   * Video Generation using veo-3.1-fast-generate-preview.
   * Max resolution 1080p with cinematic 8K-upscaling style instructions.
   */
  async generateVideo(prompt: string, aspectRatio: string, references: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const videoConfig: any = {
      model: 'veo-3.1-fast-generate-preview',
      prompt: `8K cinematic video, hyper-realistic motion: ${prompt}`,
      config: {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio: (aspectRatio === '9:16' || aspectRatio === '16:9') ? aspectRatio : '16:9'
      }
    };

    if (references.length > 0) {
      videoConfig.image = {
        imageBytes: references[0].split(',')[1],
        mimeType: references[0].split(';')[0].split(':')[1]
      };
    }

    let operation = await ai.models.generateVideos(videoConfig);

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("Video generation failed");

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  /**
   * URL analyzer for truth sheets.
   */
  async createTruthSheet(url: string): Promise<any> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze this product URL: ${url}. Extract specs and tone. Return JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            materials: { type: Type.ARRAY, items: { type: Type.STRING } },
            tone: { type: Type.ARRAY, items: { type: Type.STRING } },
            features: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['name', 'materials', 'tone', 'features']
        }
      }
    });
    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      return {};
    }
  }
}

