  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  useEffect(() => { const h = (e: any) => { if (containerRef.current && !containerRef.current.contains(e.target)) setIsOpen(false); }; document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h); }, []);
  const sel = options.find(o => o.label === value);
  return (
    <div className="space-y-2 relative flex-1" ref={containerRef}>
      <label className="text-[10px] uppercase tracking-widest text-white/40 px-2">{label}</label>
      <div onClick={() => setIsOpen(!isOpen)} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-4 text-xs flex justify-between items-center cursor-pointer hover:bg-white/10 transition-colors uppercase font-bold tracking-tighter">
