        const videoUrl = await gemini.generateVideo(finalPrompt, selection.aspectRatio, references);
        const videoResult: GenerationResult = {
          id: Math.random().toString(),
          projectId: 'current',
          url: videoUrl,
          type: 'video' as const,
          metadata: { prompt: finalPrompt, selection },
          validationScore: 100,
          validationReport: ['8K Motion Synthesis', 'Frame Fidelity Lock', 'Cinema Grade Lighting']
        };
        setResults(prev => [videoResult, ...prev]);
      }
    } catch (err: any) {
      console.error("Generation Error:", err);
      alert(`CODE RED ERROR: ${err.message || 'Generation failed. Check API connectivity.'}`);
    } finally {
      setIsGenerating(false);
    }
  };

  const startCapture = () => {
    setCaptureCount(0);
    setIsCapturing(true);
    setLightingStatus('OK');
    setAngleStatus('MISSING_BACK');
    setBlurWarning(false);
  };

