interface DropdownProps { label: string; options: any[]; value: string; onChange: (v: string) => void; }
const Dropdown: React.FC<DropdownProps> = ({ label, options, value, onChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  useEffect(() => { const h = (e: any) => { if (containerRef.current && !containerRef.current.contains(e.target)) setIsOpen(false); }; document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h); }, []);
  return (
    <div className="space-y-2 relative flex-1" ref={containerRef}>
      <label className="text-[10px] uppercase tracking-widest text-white/40 px-2 font-bold">{label}</label>
      <div onClick={() => setIsOpen(!isOpen)} className="w-full bg-white/5 border border-white/10 rounded-xl px-5 py-5 text-xs flex justify-between items-center cursor-pointer hover:bg-white/10 transition-all uppercase font-black tracking-widest">
        <span className="truncate">{value}</span><ChevronDown size={14} className={`text-white/40 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 glass rounded-2xl overflow-hidden z-[100] max-h-64 overflow-y-auto shadow-2xl">
          {options.map(o => <div key={o.id} onClick={() => { onChange(o.label); setIsOpen(false); }} className="px-5 py-4 text-[10px] uppercase font-bold hover:bg-yellow-400 hover:text-black cursor-pointer transition-colors border-b border-white/5 last:border-0">{o.label}</div>)}
        </div>
      )}
    </div>
  );
};

