import { GoogleGenAI, Type } from "@google/genai";
// Import missing constants used in compilePrompt
import { PHOTO_ANGLES, LENS_LOOKS } from "./constants";

export class GeminiService {
  /**
   * Orchestrator to compile high-fidelity prompts using Gemini 3 Pro.
   * Forces 8K UHD resolution and hyper-realistic directives.
   */
  async compilePrompt(data: any, hasReferences: boolean): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const fidelityInstruction = hasReferences 
      ? "CRITICAL: Maintain 100% exact fidelity to the provided reference images. Reproduce specific materials, logos, and textures with perfect accuracy. No hallucinations."
      : "Maintain hyper-realistic product consistency with extreme detail.";

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Compile a hyper-fidelity 8K resolution generation prompt.
      Subject: ${data.subjectType}
      Angle: ${data.angle || PHOTO_ANGLES[0].label}
      Lens: ${data.lens || LENS_LOOKS[0].label}
      Lighting: ${data.lighting}
      Style: ${data.style}
      Scene: ${data.scene}
      User Prompt: ${data.userPrompt}
      ${fidelityInstruction}
      Quality Requirements: 8K resolution, ultra-high-definition, photorealistic, 32k textures, ray-traced reflections, professional studio lighting, cinematic color grading, sharp focus.
      Constraints: Preserve logos exactly, zero creative deviation, absolute realism.

      Return ONLY the final prompt string.`,
    });
    return response.text?.trim() || "A hyper-realistic 8K professional photo.";
  }

  /**
   * Photo Generation using gemini-3-pro-image-preview.
   * Sends 8K instructions and reference images for 100% fidelity.
   */
  async generatePhotos(prompt: string, aspectRatio: string, references: string[]): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const parts: any[] = [{ text: `Generate a hyper-realistic 8K photo: ${prompt}` }];

    references.forEach(ref => {
      const parts_arr = ref.split(',');
      if (parts_arr.length > 1) {
        const mimeType = ref.split(';')[0].split(':')[1];
        const base64Data = parts_arr[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: mimeType
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts,
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K" // Note: 1K is API max, but prompt requests 8K detail for texture synthesis
        },
      },
    });

    const images: string[] = [];
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }
    }
    return images;
  }

  /**
   * Video Generation using veo-3.1-fast-generate-preview.
   * Max resolution 1080p with cinematic 8K-upscaling style instructions.
   * Robust polling with error detection.
   */
  async generateVideo(prompt: string, aspectRatio: string, references: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const videoConfig: any = {
      model: 'veo-3.1-fast-generate-preview',
      prompt: `8K cinematic masterpiece, hyper-realistic motion, ultra-detailed: ${prompt}`,
      config: {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio: (aspectRatio === '9:16' || aspectRatio === '16:9') ? aspectRatio : '16:9'
      }
    };

    // Use primary reference as seed image
    if (references.length > 0) {
      const parts_arr = references[0].split(',');
      if (parts_arr.length > 1) {
        videoConfig.image = {
          imageBytes: parts_arr[1],
          mimeType: references[0].split(';')[0].split(':')[1]
        };
      }
    }

    let operation = await ai.models.generateVideos(videoConfig);

    // Robust Polling Loop
    let attempts = 0;
    const maxAttempts = 60; // 10 mins max
    while (!operation.done && attempts < maxAttempts) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });

      if (operation.error) {
        throw new Error(`Video Operation Error: ${operation.error.message}`);
      }
      attempts++;
    }

    if (!operation.done) {
      throw new Error("Video generation timed out. Please try again.");
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("Video generation failed: No output URI returned.");

    // Fetch MP4 content with API key auth
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    if (!response.ok) throw new Error(`Failed to fetch video content: ${response.statusText}`);

    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  /**
   * URL analyzer for truth sheets.
   */
  async createTruthSheet(url: string): Promise<any> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze this product URL: ${url}. Extract canonical specs, logo positions, and brand tone. Return JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            materials: { type: Type.ARRAY, items: { type: Type.STRING } },
            tone: { type: Type.ARRAY, items: { type: Type.STRING } },
            features: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['name', 'materials', 'tone', 'features']
        }
      }
    });
    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      return {};
    }
  }
}

