import { GoogleGenAI, Type } from "@google/genai";
import { PHOTO_ANGLES, LENS_LOOKS } from "./constants";

export class GeminiService {
  /**
   * Orchestrator to compile prompts that prioritize technical fidelity.
   * Strips away creative "fluff" and focuses on literal, physical product description.
   */
  async compilePrompt(data: any, hasReferences: boolean): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemInstruction = `You are a Technical Product Photography Specialist. 
    Your goal is to generate a prompt that results in a 100% EXACT physical replica of the subject.
    DO NOT add artistic flair. DO NOT add extra objects. 
    Focus on: Material (brushed aluminum, matte polycarbonate), Color (exact shades), Logo placement (centered, embossed), and Hardware (zippers, wheels, stitching).
    ZERO DEVIATION from reference images is the absolute priority.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Compile a literal, high-fidelity description for:
      Subject: ${data.subjectType}
      User Inputs: ${data.userPrompt}
      Current Settings: ${data.angle}, ${data.lens}, ${data.lighting}, ${data.style}, ${data.scene}.

      Requirements: 8K resolution, photorealistic, sharp focus, literal material description, exact brand fidelity.`,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.1, // Low temperature for high consistency
      }
    });
    return response.text?.trim() || "A hyper-realistic 8K professional product photo.";
  }

  /**
   * Photo Generation using gemini-3-pro-image-preview.
   * Enforces 1K raw generation with 8K texture synthesis.
   */
  async generatePhotos(prompt: string, aspectRatio: string, references: string[]): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const parts: any[] = [{ text: `8K MASTERPIECE, PIXEL-PERFECT FIDELITY: ${prompt}` }];

    references.forEach(ref => {
      const parts_arr = ref.split(',');
      if (parts_arr.length > 1) {
        const mimeType = ref.split(';')[0].split(':')[1];
        const base64Data = parts_arr[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: mimeType
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts,
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        },
      },
    });

    const images: string[] = [];
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }
    }
    return images;
  }

  /**
   * High-Fidelity Video Generation using veo-3.1-generate-preview.
   * Implements multi-reference ASSET system for 16:9 or Start-Frame for 9:16.
   */
  async generateVideo(prompt: string, aspectRatio: string, references: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Switch to higher quality model
    const model = 'veo-3.1-generate-preview';
    const finalPrompt = `100% EXACT PRODUCT REPLICA, PIXEL-PERFECT, 8K, ${prompt}`;

    let videoConfig: any = {
      model: model,
      prompt: finalPrompt,
      config: {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio: (aspectRatio === '9:16' || aspectRatio === '16:9') ? aspectRatio : '16:9'
      }
    };

    // LOGIC FOR 100% FIDELITY:
    // If multiple references are available and aspect is 16:9, use ASSET referencing
    if (references.length > 1 && aspectRatio === '16:9') {
      const referenceImagesPayload: any[] = references.slice(0, 3).map(ref => ({
        image: {
          imageBytes: ref.split(',')[1],
          mimeType: ref.split(';')[0].split(':')[1]
        },
        referenceType: 'ASSET'
      }));

      videoConfig.config.referenceImages = referenceImagesPayload;
      videoConfig.config.resolution = '720p'; // Required for multi-ref
    } else if (references.length > 0) {
      // Use standard image-start frame for non-16:9 to lock initial fidelity
      videoConfig.image = {
        imageBytes: references[0].split(',')[1],
        mimeType: references[0].split(';')[0].split(':')[1]
      };
    }

    let operation = await ai.models.generateVideos(videoConfig);

    let attempts = 0;
    const maxAttempts = 120; // 20 mins
    while (!operation.done && attempts < maxAttempts) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });

      if (operation.error) throw new Error(`Video Error: ${operation.error.message}`);
      attempts++;
    }

    if (!operation.done) throw new Error("Video generation timed out.");

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No video output produced.");

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async createTruthSheet(url: string): Promise<any> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze ${url}. Extract physical specifications, materials, and logos. Return JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            materials: { type: Type.ARRAY, items: { type: Type.STRING } },
            tone: { type: Type.ARRAY, items: { type: Type.STRING } },
            features: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['name', 'materials', 'tone', 'features']
        }
      }
    });
    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      return {};
    }
  }
}

