import { GoogleGenAI, Type } from "@google/genai";
import { PHOTO_ANGLES, LENS_LOOKS } from "./constants";

export class GeminiService {
  /**
   * Orchestrator to compile prompts that prioritize technical fidelity.
   * Strips away creative "fluff" and focuses on literal, physical product description.
   * Now includes Thinking Mode for complex orchestration.
   */
  async compilePrompt(data: any, hasReferences: boolean): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const fidelityInstruction = data.creativeDeviation 
      ? "Feel free to be creative and deviate from the exact reference while keeping the essence."
      : "You MUST prioritize 100% literal physical fidelity. DO NOT hallucinate extra features. Describe the subject exactly as seen in reference images, including hardware, textures, and labels.";

    const systemInstruction = `You are a Technical Product Photography Specialist. 
    Your goal is to generate a prompt that results in a 100% EXACT physical replica of the subject.
    Focus on: Material, Color, Logo placement, and Hardware.
    ${fidelityInstruction}`;

    const config: any = {
      systemInstruction: systemInstruction,
      temperature: data.creativeDeviation ? 0.7 : 0.1,
    };

    if (data.thinkingMode) {
      config.thinkingConfig = { thinkingBudget: 32768 };
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Compile a literal, high-fidelity description for:
      Subject: ${data.subjectType}
      User Inputs: ${data.userPrompt}
      Settings: ${data.angle}, ${data.lens}, ${data.lighting}, ${data.style}, ${data.scene}.

      Requirements: 8K resolution, photorealistic, sharp focus, literal material description, exact brand fidelity.`,
      config: config
    });

    return response.text?.trim() || "A hyper-realistic 8K professional product photo.";
  }

  /**
   * Photo Generation using gemini-3-pro-image-preview.
   * Maps user requested aspect ratios to API supported values.
   */
  async generatePhotos(prompt: string, aspectRatio: string, references: string[]): Promise<string[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // API Mapping for gemini-3-pro-image-preview
    const apiAspectRatioMap: Record<string, any> = {
      '1:1': '1:1',
      '3:4': '3:4',
      '4:3': '4:3',
      '9:16': '9:16',
      '16:9': '16:9',
      '2:3': '3:4', // closest
      '3:2': '4:3', // closest
      '21:9': '16:9' // closest
    };

    const parts: any[] = [{ text: `8K MASTERPIECE, PIXEL-PERFECT FIDELITY: ${prompt}` }];

    references.forEach(ref => {
      const parts_arr = ref.split(',');
      if (parts_arr.length > 1) {
        const mimeType = ref.split(';')[0].split(':')[1];
        const base64Data = parts_arr[1];
        parts.push({
          inlineData: {
            data: base64Data,
            mimeType: mimeType
          }
        });
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts,
      },
      config: {
        imageConfig: {
          aspectRatio: apiAspectRatioMap[aspectRatio] || '1:1',
          imageSize: "1K"
        },
      },
    });

    const images: string[] = [];
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          images.push(`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`);
        }
      }
    }
    return images;
  }

  /**
   * Image editing using Gemini 2.5 Flash Image.
   */
  async editImage(base64Image: string, editPrompt: string): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const mimeType = base64Image.split(';')[0].split(':')[1];
    const base64Data = base64Image.split(',')[1];

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Data, mimeType } },
          { text: `Edit this image based on the following instruction: ${editPrompt}. Maintain as much original fidelity as possible.` }
        ]
      }
    });

    let imageUrl = '';
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          break;
        }
      }
    }
    return imageUrl;
  }

  /**
   * High-Fidelity Video Generation using veo-3.1-generate-preview.
   * Optimized for 100% product fidelity.
   */
  async generateVideo(prompt: string, aspectRatio: string, references: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Force portrait for social/iphone look if requested, else 16:9
    const targetAspect = aspectRatio === '9:16' ? '9:16' : '16:9';

    const videoPrompt = `EXACT PRODUCT REPLICA MOTION: ${prompt}. Focus on maintaining the exact structural integrity of the subject shown in references. No warping, no distortions.`;

    const config: any = {
      model: 'veo-3.1-generate-preview',
      prompt: videoPrompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: targetAspect
      }
    };

    if (references.length > 0) {
      // Use the first reference as the primary starting frame for maximum fidelity
      const ref = references[0];
      config.image = {
        imageBytes: ref.split(',')[1],
        mimeType: ref.split(';')[0].split(':')[1]
      };
    }

    let operation = await ai.models.generateVideos(config);

    let attempts = 0;
    const maxAttempts = 120; // Allow plenty of time for high-res generation
    while (!operation.done && attempts < maxAttempts) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
      if (operation.error) throw new Error(`Veo Generation Error: ${operation.error.message}`);
      attempts++;
    }

    if (!operation.done) throw new Error("Video generation timed out.");

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No video output produced.");

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);
  }

  async createTruthSheet(url: string): Promise<any> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze ${url}. Extract canonical specs, logo positions, and brand tone. Return JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            materials: { type: Type.ARRAY, items: { type: Type.STRING } },
            tone: { type: Type.ARRAY, items: { type: Type.STRING } },
            features: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ['name', 'materials', 'tone', 'features']
        }
      }
    });
    try {
      return JSON.parse(response.text || "{}");
    } catch (e) {
      return {};
    }
  }
}

